<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factura {{ $invoice->number }}</title><style>body{font-family:Arial,sans-serif;max-width:900px;margin:40px auto;padding:20px;color:#102c44}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}h1{color:#158038}dt{font-weight:bold}dd{margin:0 0 14px}small{color:#53697a}</style></head><body><h1>{{ $invoice->issuer['company_name'] ?? 'All True Detection' }}</h1><h2>Factura comercial</h2><p>{{ $invoice->number }}</p><p>Emitida: {{ $invoice->issued_at->format('d/m/Y') }} · Vence: {{ $invoice->due_date?->format('d/m/Y') ?? 'No definido' }}</p><p><strong>Cliente:</strong> {{ $invoice->recipient['name'] ?? '' }}<br>{{ $invoice->recipient['billing_email'] ?? '' }}<br>{{ $invoice->recipient['billing_address'] ?? '' }}</p><table><thead><tr><th>Servicio</th><th>Cantidad</th><th>Precio unitario</th><th>Total</th></tr></thead><tbody>@foreach($invoice->order->items as $item)<tr><td>{{ $item->service_name }}</td><td>{{ $item->quantity }}</td><td>{{ \App\Support\Money::format($item->unit_price,$invoice->currency) }}</td><td>{{ \App\Support\Money::format($item->unit_price*$item->quantity,$invoice->currency) }}</td></tr>@endforeach</tbody></table><dl><dt>Subtotal</dt><dd>{{ \App\Support\Money::format($invoice->subtotal,$invoice->currency) }}</dd><dt>Impuesto</dt><dd>{{ \App\Support\Money::format($invoice->tax,$invoice->currency) }}</dd><dt>Total</dt><dd>{{ \App\Support\Money::format($invoice->total,$invoice->currency) }}</dd><dt>Pagado</dt><dd>{{ \App\Support\Money::format($invoice->paidAmount(),$invoice->currency) }}</dd><dt>Pendiente</dt><dd>{{ \App\Support\Money::format($invoice->outstanding(),$invoice->currency) }}</dd></dl><small>Documento comercial sin NCF. El pago es coordinado y confirmado por ATD.</small></body></html>
